import csv, io, json, os, re, sys, unicodedata


def nid(s):
    return str(s).strip().lower()


def fold(s):
    s = s.casefold()
    s = ''.join(ch if unicodedata.category(ch)[0] in 'LN' else ' ' for ch in s)
    return ' '.join(s.split())


def read_batches(cvr):
    files = []
    for n in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, n)
        if os.path.isfile(p) and (n.endswith('.csv') or n.endswith('.jsonl')):
            files.append(p)
    out = []  # (batch, rev, status, records)  record=(contest, {rank: [marks]})
    for p in files:
        with open(p, encoding='utf-8', newline='') as f:
            text = f.read()
        lines = text.split('\n')
        recs = []
        if p.endswith('.jsonl'):
            meta = None
            for ln in lines:
                if not ln.strip():
                    continue
                o = json.loads(ln)
                if meta is None:
                    meta = o
                    continue
                rk = {}
                for m in o.get('marks', []):
                    r = int(m['rank'])
                    if 'candidate' in m and m['candidate'] is not None:
                        rk.setdefault(r, []).append(('c', m['candidate']))
                    elif m.get('write_in') is not None:
                        rk.setdefault(r, []).append(('w', m['write_in']))
                recs.append((o['contest'], rk))
        else:
            meta = {}
            body = []
            for ln in lines:
                if ln.startswith('#'):
                    mm = re.match(r'#\s*([^:]*?)\s*:\s*(.*?)\s*$', ln.rstrip('\r'))
                    if mm:
                        meta[mm.group(1).strip().lower()] = mm.group(2)
                elif ln.strip():
                    body.append(ln)
            rows = list(csv.reader(io.StringIO('\n'.join(body))))
            hdr = [h.strip().lower() for h in rows[0]]
            ci = hdr.index('contest')
            rcols = []
            for i, h in enumerate(hdr):
                mm = re.fullmatch(r'rank(\d+)', h)
                if mm:
                    rcols.append((int(mm.group(1)), i))
            for row in rows[1:]:
                if not row:
                    continue
                rk = {}
                for r, i in rcols:
                    if i < len(row) and row[i] != '':
                        for part in row[i].split('|'):
                            if part == '':
                                continue
                            if part.startswith('WI:'):
                                rk.setdefault(r, []).append(('w', part[3:]))
                            else:
                                rk.setdefault(r, []).append(('c', part))
                recs.append((row[ci], rk))
        out.append((str(meta['batch']), int(str(meta['revision']).strip()),
                    str(meta['status']).strip().lower(), recs))
    return out


def read_ballot(rk, mr, wmap, withdrawn):
    """returns list of rankings: ('skip',) ('pass',) ('c', id) ('over', ids)"""
    seen = set()
    res = []
    for r in range(1, mr + 1):
        marks = set()
        for kind, v in rk.get(r, []):
            if kind == 'w':
                w = wmap.get(fold(v))
                if w is not None:
                    marks.add(w)
            else:
                marks.add(nid(v))
        if not marks:
            res.append(('skip',))
            continue
        marks -= withdrawn
        if not marks:
            res.append(('pass',))
            continue
        new = marks - seen
        seen |= marks
        if not new:
            res.append(('skip',))
        elif len(new) == 1:
            res.append(('c', next(iter(new))))
        else:
            res.append(('over',))
    return res


def count(rb, cont):
    tal = {c: 0 for c in cont}
    exh = 0
    for rs in rb:
        n = len(rs)
        i = 0
        dest = None
        while i < n:
            s = rs[i]
            if s[0] == 'c':
                if s[1] in cont:
                    dest = s[1]
                    break
            elif s[0] == 'over':
                break
            elif s[0] == 'skip':
                if i + 1 < n and rs[i + 1][0] == 'skip':
                    break
                if i + 1 >= n:
                    break
            i += 1
        if dest is None:
            exh += 1
        else:
            tal[dest] += 1
    return tal, exh


def run_contest(c, recs):
    mr = c['max_ranks']
    names = {}
    withdrawn = set()
    cands = []
    for x in c['candidates']:
        k = nid(x['id'])
        names[k] = x['id']
        if x.get('status') == 'active':
            cands.append(k)
        else:
            withdrawn.add(k)
    wmap = {}
    for w in c.get('write_ins', []):
        k = nid(w['id'])
        names[k] = w['id']
        cands.append(k)
        for t in [w['name']] + list(w.get('aliases', [])):
            wmap[fold(t)] = k
    lot = {nid(x): i for i, x in enumerate(c.get('lot_order', []))}
    rb = [read_ballot(rk, mr, wmap, withdrawn) for rk in recs]
    total = len(rb)
    cont = set(cands)
    rounds = []
    hist = []
    winner = None
    while True:
        tal, exh = count(rb, cont)
        active = total - exh
        rd = {'round': len(rounds) + 1,
              'tallies': {names[k]: v for k, v in tal.items()},
              'exhausted': exh, 'eliminated': []}
        rounds.append(rd)
        hist.append(tal)
        if active == 0:
            break
        win = [k for k, v in tal.items() if v * 2 > active]
        if win:
            winner = win[0]
            break
        if len(cont) == 1:
            winner = next(iter(cont))
            break
        zeros = [k for k, v in tal.items() if v == 0]
        if zeros:
            elim = zeros
        else:
            m = min(tal.values())
            tied = [k for k, v in tal.items() if v == m]
            j = len(hist) - 2
            while len(tied) > 1 and j >= 0:
                mm = min(hist[j][k] for k in tied)
                tied = [k for k in tied if hist[j][k] == mm]
                j -= 1
            if len(tied) > 1:
                tied = [max(tied, key=lambda k: lot.get(k, -1))]
            elim = tied
        rd['eliminated'] = sorted(names[k] for k in elim)
        cont -= set(elim)
    return {'contest': c['id'], 'ballots': total,
            'winner': names[winner] if winner else None, 'rounds': rounds}


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, 'election.json'), encoding='utf-8') as f:
        el = json.load(f)
    best = {}
    for b, rev, st, recs in read_batches(os.path.join(inp, 'cvr')):
        if b not in best or rev > best[b][0]:
            best[b] = (rev, st, recs)
    by = {c['id']: [] for c in el['contests']}
    for rev, st, recs in best.values():
        if st != 'final':
            continue
        for cid, rk in recs:
            if cid in by:
                by[cid].append(rk)
    res = {'election': el['election'],
           'contests': [run_contest(c, by[c['id']]) for c in el['contests']]}
    with open(outp, 'w', encoding='utf-8') as f:
        json.dump(res, f, ensure_ascii=False, indent=1)


main()
